package com.centaurlabs.est

import org.junit.Assert.*
import org.junit.Test
import java.time.LocalDate
import kotlin.random.Random

class LatestIosTest {
    @Test fun dailyMatchesSwiftOracle() {
        // Generated by running the unchanged iOS SeededGenerator.swift and Swift Array.shuffled.
        val expected = "6,52,80,75,58,54,77,63,19,10,29,27,38,59,37,47,12,70,5,51,61,78,35,28,64,32,55,76,9,13,0,20,2,24,7,4,79,41,50,17,73,65,33,23,39,30,42,25,72,16,45,48,62,31,57,40,3,1,11,46,69,22,60,68,53,43,67,56,26,49,34,8,18,66,14,71,21,44,36,74,15".split(',').map(String::toInt)
        assertEquals(expected, DailyDeck.cards(LocalDate.parse("2026-11-01")))
        assertEquals(listOf(51,23,58,42,11,54), DailyDeck.cards(LocalDate.parse("2026-10-31")).take(6))
        assertEquals(listOf(70,40,75,18,16,79), DailyDeck.cards(LocalDate.parse("2024-02-29")).take(6))
    }
    @Test fun everyQuickTraitCanFinishAndRestore() {
        for (trait in 0..3) {
            var now = 0L
            var game = Game({ now }, Mode.QUICK, Random(trait), quickTrait = trait)
            assertEquals(27, (game.table + game.deck).size)
            assertTrue((game.table + game.deck).all { EstCard(it).traits[trait] == 0 })
            val saved = game.save(1000)
            game = Game.restore(saved, 1001) { now }!!
            assertEquals(trait, game.quickTrait); game.resume()
            while (!game.finished) {
                EstCard.find(game.table.map(::EstCard))!!.forEach { game.select(it.id) }
                now += 1000; game.tick()
            }
            assertEquals((Mode.QUICK.deck(trait)).toSet(), (game.done + game.table).toSet())
        }
    }
    @Test fun hintShowsTwoOfSameSetAndResetsAfterMatch() {
        var now = 0L
        val game = Game({ now }, Mode.FULL, Random(12))
        game.hint(); val first = game.hinted.single()
        game.select(first); game.select(first)
        game.hint(); assertEquals(2, game.hinted.size); assertTrue(first in game.hinted)
        game.hint(); assertEquals(2, game.hinted.size)
        val cards = game.hinted.map(::EstCard)
        (cards + EstCard.complete(cards[0],cards[1])).forEach { game.select(it.id) }
        now = 1000; game.tick(); assertTrue(game.hinted.isEmpty())
    }
    @Test fun learningPreservesUnhintedFastestAndResetsStreakOnMiss() {
        val stats = PlayerStats()
        val set = listOf(0,1,2).map(::EstCard)
        stats.record(set, 1, 5.0); stats.record(set, 1, 1.0, hinted = true)
        assertEquals(5.0, stats.fastestSet!!, 0.0); assertEquals(2, stats.longestStreak)
        stats.record(listOf(0,1,3).map(::EstCard), 1, 6.0)
        assertEquals(0, stats.currentStreak)
        for (trait in 0..3) repeat(50) {
            assertEquals(listOf(trait), EstCard.audit(EstCard.nearMiss(trait)).mapIndexedNotNull { i, ok -> if (ok) null else i })
        }
    }
    @Test fun wideBoardUsesLargerRotatedLayout() {
        val layout = CardGeometry.boardLayout(700f,400f,12,240f)
        assertEquals(4,layout.columns); assertEquals(3,layout.rows)
        assertEquals(126.666664f,layout.side,.001f)
    }
}
